import React, { useState, useEffect } from 'react';
import { Difficulty } from '../../types';
import { Storage } from '../../utils/storage';
import { Icons } from '../ui/Icons';
import { Logo } from '../ui/Logo';
import { sounds } from '../../utils/sound';
import { getDifficultyPoints, DIFFICULTY_DESCRIPTIONS } from '../../utils/constants';

interface DifficultyScreenProps {
    points: number;
    onDifficultySelect: (diff: Difficulty) => void;
    onOpenSettings: () => void;
    onOpenStore: () => void;
    onOpenDiamondShop: () => void;
    onClaimBonus: () => void;
    onOpenStats: () => void;
    nextBonusClaimTime: number;
    hiddenDifficulties?: Difficulty[]; // New prop
}

// Internal Hook for Counting Animation
const useAnimatedCounter = (target: number, duration: number = 500) => {
    const [count, setCount] = useState(0);

    useEffect(() => {
        let startTime: number | null = null;
        let animationFrameId: number;

        // Reset start value to 0 on target change to trigger animation
        setCount(0);

        const animate = (currentTime: number) => {
            if (!startTime) startTime = currentTime;
            const progress = Math.min((currentTime - startTime) / duration, 1);

            // Cubic Ease Out
            const ease = 1 - Math.pow(1 - progress, 3); 

            setCount(Math.floor(target * ease));

            if (progress < 1) {
                animationFrameId = requestAnimationFrame(animate);
            } else {
                setCount(target);
            }
        };

        animationFrameId = requestAnimationFrame(animate);

        return () => {
            if (animationFrameId) cancelAnimationFrame(animationFrameId);
        };
    }, [target, duration]);

    return count;
};

// Sub-component for individual cards
const DifficultyCard: React.FC<{
    diff: Difficulty;
    index: number;
    onSelect: (diff: Difficulty) => void;
    activeInfo: Difficulty | null;
    onInfoToggle: (diff: Difficulty) => void;
    isClosing: boolean;
    description: string;
    isPyramidTop?: boolean; // Prop to handle pyramid layout centering
    contentScale?: 'normal' | 'medium' | 'large';
    layoutStyle?: React.CSSProperties;
}> = ({ diff, index, onSelect, activeInfo, onInfoToggle, isClosing, description, isPyramidTop, contentScale = 'normal', layoutStyle }) => {

    // Data Loading
    const completed = Storage.getCompletedCount(diff, 300);
    const isPack2Unlocked = Storage.isPack2Unlocked(diff);
    const isPack3Unlocked = Storage.isPack3Unlocked(diff);

    let maxLevels = 100;
    if (isPack2Unlocked) maxLevels = 200;
    if (isPack3Unlocked) maxLevels = 300;

    const diffPoints = getDifficultyPoints(diff);

    // Animation Logic
    const delay = 100 + (index * 50); // Linear delay based on index is smoother

    const isInfoActive = activeInfo === diff;
    // If pyramid top, tooltip should default to right or calculate based on screen
    const isLeftColumn = isPyramidTop ? true : index % 2 === 0;

    // State to track if entry animation is done
    const [animating, setAnimating] = useState(true);
    useEffect(() => {
        const t = setTimeout(() => {
            setAnimating(false);
        }, delay + 600); // delay + animation duration (400ms) + buffer
        return () => clearTimeout(t);
    }, [delay]);

    // Z-Index Logic
    const baseZIndex = 30 - index; // Simple z-index stack
    const finalZIndex = isInfoActive ? 100 : baseZIndex;

    // Use animated counter hook
    const animatedCompleted = useAnimatedCounter(completed, 500);

    const progressPercent = Math.min((animatedCompleted / maxLevels) * 100, 100);

    // Default Style fallback (Grid Layout)
    const defaultStyle: React.CSSProperties = {
        width: '47.5%',
        aspectRatio: '1.55/1', 
    };

    const finalStyle = { ...defaultStyle, ...layoutStyle, zIndex: finalZIndex, animationDelay: `${delay}ms` };

    // Dynamic Scale classes
    const titleClass = contentScale === 'large' ? 'text-3xl mb-3' : (contentScale === 'medium' ? 'text-2xl mb-2' : 'text-lg mb-1');
    const iconSizeClass = contentScale === 'large' ? 'w-6 h-6' : (contentScale === 'medium' ? 'w-5 h-5' : 'w-3.5 h-3.5');
    const infoIconSizeClass = contentScale === 'large' ? 'w-8 h-8 -ml-1.5' : (contentScale === 'medium' ? 'w-7 h-7 -ml-1' : 'w-6 h-6 -ml-0.5');
    const infoIconInnerSize = contentScale === 'large' ? 'w-6 h-6' : (contentScale === 'medium' ? 'w-5 h-5' : 'w-4 h-4');
    const pointsTextClass = contentScale === 'large' ? 'text-xl' : (contentScale === 'medium' ? 'text-lg' : 'text-sm');
    const progressTextClass = contentScale === 'large' ? 'text-xl' : (contentScale === 'medium' ? 'text-lg' : 'text-sm');
    const progressBarHeight = contentScale === 'large' ? 'h-3' : (contentScale === 'medium' ? 'h-2.5' : 'h-1.5');
    const paddingClass = contentScale === 'large' ? 'p-6' : (contentScale === 'medium' ? 'p-5' : 'p-3.5');

    return (
        <button 
            onClick={() => onSelect(diff)} 
            style={finalStyle}
            className={`bg-t-surface ${paddingClass} rounded-2xl shadow-sm flex flex-col justify-between active:scale-95 transition-transform text-left relative group overflow-visible ${animating ? 'opacity-0 animate-slide-in-down' : 'opacity-100'}`}
        >
            {/* Header: Title & Points */}
            <div className="w-full flex justify-between items-start mb-1">
                <span className={`font-semibold text-stone-700 dark:text-stone-300 leading-none tracking-tight truncate mr-1 mt-0.5 ${titleClass}`}>{diff}</span>
                <div className="flex items-center gap-1 shrink-0">
                    <span className={`${pointsTextClass} font-bold text-t-primary opacity-80 leading-none`}>+{diffPoints}</span>
                    <Icons.Diamond className={`${iconSizeClass} text-blue-500 fill-current`} />
                </div>
            </div>

            {/* Middle: Info & Progress Numbers */}
            <div className="w-full flex justify-between items-end mb-2 mt-auto">
                {/* Info Icon */}
                <div className="relative z-50" onClick={(e) => e.stopPropagation()}>
                    <div 
                        role="button"
                        onClick={() => onInfoToggle(diff)}
                        className={`flex items-center justify-center cursor-pointer hover:bg-stone-100 dark:hover:bg-stone-700 rounded-full transition-colors ${infoIconSizeClass}`}
                    >
                        <Icons.Info className={`${infoIconInnerSize} transition-colors ${isInfoActive ? 'text-stone-800 dark:text-stone-200' : 'text-stone-400 dark:text-stone-500'}`} />
                    </div>

                    {/* Tooltip */}
                    {isInfoActive && (
                        <div 
                            className={`absolute top-full mt-2 w-44 z-[60] cursor-default ${
                                isLeftColumn 
                                    ? '-left-2 origin-top-left' 
                                    : '-right-2 origin-top-right'
                            } ${isClosing ? 'animate-tooltip-exit' : 'animate-tooltip-enter'}`}
                            onClick={(e) => e.stopPropagation()}
                        >
                            <div className="bg-white text-stone-900 text-xs font-medium p-3 rounded-xl relative text-left leading-relaxed border border-stone-400 dark:border-stone-500 shadow-lg">
                                {description}
                                <div className={`absolute -top-[6px] w-3 h-3 bg-white border-t border-l border-stone-400 dark:border-stone-500 transform rotate-45 ${
                                    isLeftColumn ? 'left-[14px]' : 'right-[14px]'
                                }`}></div>
                            </div>
                        </div>
                    )}
                </div>

                {/* Progress Numbers (Animated) */}
                <span className={`${progressTextClass} text-stone-700 dark:text-stone-300 font-bold tracking-wide font-sans leading-none`}>
                    {animatedCompleted} / {maxLevels}
                </span>
            </div>

            {/* Bottom: Progress Bar (Animated) */}
            <div className={`w-full bg-t-surface-sec rounded-full overflow-hidden ${progressBarHeight}`}>
                <div 
                    className="h-full bg-loading-blue" 
                    style={{ 
                        width: `${progressPercent}%`,
                        transition: 'width 0.1s linear' 
                    }}
                ></div>
            </div>
        </button>
    );
};

export const DifficultyScreen: React.FC<DifficultyScreenProps> = ({ 
    points, 
    onDifficultySelect, 
    onOpenSettings, 
    onOpenStore, 
    onOpenDiamondShop, 
    onClaimBonus, 
    onOpenStats, 
    nextBonusClaimTime,
    hiddenDifficulties = [] 
}) => {
    const [timeLeft, setTimeLeft] = useState<string>("");
    const [activeInfo, setActiveInfo] = useState<Difficulty | null>(null);
    const [isClosing, setIsClosing] = useState(false);

    const [infoIndices, setInfoIndices] = useState<Record<string, number>>({});

    useEffect(() => {
        const updateTimer = () => {
            const now = Date.now();
            if (now >= nextBonusClaimTime) {
                setTimeLeft("");
                return;
            }
            setTimeLeft("See you tomorrow!");
        };

        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [nextBonusClaimTime]);

    const handleClose = () => {
        if (!activeInfo) return;
        setIsClosing(true);
        const closingDiff = activeInfo;
        setTimeout(() => {
            setActiveInfo(null);
            setIsClosing(false);
            setInfoIndices(prev => ({
                ...prev,
                [closingDiff]: (prev[closingDiff] || 0) + 1
            }));
        }, 150);
    };

    const handleInfoToggle = (diff: Difficulty) => {
        sounds.playTap();
        if (activeInfo === diff) {
            handleClose();
        } else {
            setActiveInfo(diff);
            setIsClosing(false);
        }
    };

    // Filter Difficulties
    const visibleDifficulties = Object.values(Difficulty).filter(d => !hiddenDifficulties.includes(d));
    const isOddCount = visibleDifficulties.length % 2 !== 0;
    const isVerticalStack = visibleDifficulties.length === 2;
    const isOneVisible = visibleDifficulties.length === 1;

    return (
        <div 
            className="flex-1 w-full flex flex-col items-center overflow-hidden" 
            onClick={() => activeInfo && handleClose()}
        >
             {/* Content Container - removed overflow-y-auto, added overflow-hidden for non-scrollable */}
             <div className="flex-1 w-full overflow-hidden px-6 pb-6 pt-4 flex flex-col items-center min-h-0">

                  {/* Hero Section - Static */}
                  <div className="flex flex-col items-center mb-6 shrink-0">
                      <Logo size={70} className="mb-4 drop-shadow-xl" />
                      <h1 className="text-3xl font-semibold text-t-primary mb-2 tracking-tight">Oku</h1>
                      <div className="h-px w-12 bg-t-border mb-3"></div>
                  </div>

                  {/* Difficulty Header */}
                  <div 
                    className="w-full max-w-md flex justify-center mb-2 opacity-0 animate-slide-in-down shrink-0" 
                    style={{ animationDelay: '50ms' }}
                  >
                      <p className="text-xs font-semibold text-t-secondary uppercase tracking-[0.2em]">Choose your pace</p>
                  </div>

                  {/* Difficulty Grid */}
                  <div className="w-full max-w-md flex flex-wrap justify-center gap-3 mb-8 shrink-0 min-h-[330px] content-center">
                      {visibleDifficulties.map((diff, index) => {
                          const descriptions = DIFFICULTY_DESCRIPTIONS[diff];
                          const currentIndex = infoIndices[diff] || 0;
                          const description = descriptions[currentIndex % descriptions.length];

                          // Pyramid Layout Logic:
                          // If odd total, the first item (index 0) becomes top of pyramid.
                          // Exclude single item case from pyramid top logic to avoid wrapper redundancy if not needed
                          const isPyramidTop = isOddCount && index === 0 && !isOneVisible;

                          // Determine dynamic sizing props
                          let contentScale: 'normal' | 'medium' | 'large' = 'normal';
                          let layoutStyle: React.CSSProperties = {};

                          if (isOneVisible) {
                              layoutStyle = { width: '62%', aspectRatio: '1.55/1' };
                              contentScale = 'normal';
                          } else if (isVerticalStack) {
                              layoutStyle = { width: '55%', aspectRatio: '1.55/1' };
                              contentScale = 'normal';
                          } else if (isPyramidTop) {
                              // Pyramid top (odd count) - Standard size but centered wrapper
                              layoutStyle = { width: '47.5%', aspectRatio: '1.55/1' };
                          }

                          if (isPyramidTop || isVerticalStack) {
                              // Wrap the top item (or all items if vertical stack) in a full-width container to force a new row and centering
                              return (
                                  <div key={diff} className="w-full flex justify-center">
                                      <DifficultyCard 
                                          diff={diff}
                                          index={index}
                                          onSelect={onDifficultySelect}
                                          activeInfo={activeInfo}
                                          onInfoToggle={handleInfoToggle}
                                          isClosing={isClosing && activeInfo === diff}
                                          description={description}
                                          isPyramidTop={true}
                                          contentScale={contentScale}
                                          layoutStyle={layoutStyle}
                                      />
                                  </div>
                              );
                          }

                          return (
                              <DifficultyCard 
                                  key={diff}
                                  diff={diff}
                                  index={index}
                                  onSelect={onDifficultySelect}
                                  activeInfo={activeInfo}
                                  onInfoToggle={handleInfoToggle}
                                  isClosing={isClosing && activeInfo === diff}
                                  description={description}
                                  contentScale={contentScale}
                                  layoutStyle={layoutStyle}
                              />
                          );
                      })}
                  </div>

                  {/* Footer Actions */}
                  <div className="w-full max-w-md flex flex-col gap-3 shrink-0">
                      {/* Row 1: Store & Get More */}
                      <div 
                        className="flex justify-center gap-3 opacity-0 animate-slide-in-down w-full" 
                        style={{ animationDelay: '250ms' }}
                      >
                          <button 
                            onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenStore(); }} 
                            style={{ width: '47.5%', background: 'linear-gradient(135deg, #E8BA6E 0%, #B78B4D 100%)' }}
                            className="p-4 text-[#3f2e18] rounded-2xl shadow-[0_2px_8px_rgba(0,0,0,0.08)] flex items-center justify-center gap-2 active:scale-95 transition relative"
                          >
                              <Icons.Store className="w-5 h-5" /> <span className="font-semibold tracking-wide">Store</span>
                          </button>

                          <button 
                            onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenDiamondShop(); }} 
                            style={{ width: '47.5%', background: 'linear-gradient(135deg, #ffffff 0%, #f1f5f9 50%, #cbd5e1 100%)' }}
                            className="p-4 text-slate-800 rounded-2xl shadow-[0_2px_8px_rgba(0,0,0,0.08)] flex items-center justify-center gap-2 active:scale-95 transition-all relative overflow-hidden"
                          >
                              <div className="absolute bottom-0 inset-x-0 h-12 bg-gradient-to-t from-blue-100/30 to-transparent pointer-events-none" />
                              <div className="absolute inset-0 -translate-x-full animate-[shimmer_4s_infinite] bg-gradient-to-r from-transparent via-white/80 to-transparent skew-x-[-20deg] pointer-events-none" />
                              <span className="font-bold tracking-wide relative z-10 text-slate-700">Get More</span> 
                              <Icons.Diamond className="w-4 h-4 text-blue-500 fill-current relative z-10 drop-shadow-sm" />
                          </button>
                      </div>

                      {/* Row 2: Stats & Bonus */}
                      <div 
                        className="flex justify-center gap-3 opacity-0 animate-slide-in-down w-full"
                        style={{ animationDelay: '300ms' }}
                      >
                          <button 
                            onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenStats(); }} 
                            style={{ width: '47.5%', background: 'linear-gradient(135deg, #B8D3F5 0%, #79A6E3 100%)' }}
                            className="p-4 text-[#102a43] rounded-2xl shadow-[0_2px_8px_rgba(0,0,0,0.08)] flex items-center justify-center gap-2 active:scale-95 transition"
                          >
                              <Icons.BarChart className="w-5 h-5" /> <span className="font-semibold tracking-wide">Stats</span>
                          </button>

                          <button 
                              onClick={(e) => { e.stopPropagation(); onClaimBonus(); }}
                              disabled={!!timeLeft}
                              style={{ width: '47.5%', ...(!timeLeft ? { background: 'linear-gradient(135deg, #B8DBBE 0%, #8CB794 100%)' } : {}) }}
                              className={`p-4 rounded-2xl flex items-center justify-center gap-2 transition overflow-hidden relative ${
                                  !!timeLeft 
                                  ? 'bg-t-surface-sec border-t-border text-t-secondary cursor-not-allowed shadow-sm' 
                                  : 'text-[#163c20] shadow-[0_2px_8px_rgba(0,0,0,0.08)] active:scale-95'
                              }`}
                          >
                              {!!timeLeft ? (
                                   <div className="flex items-center gap-2 h-6">
                                      <Icons.Clock className="w-4 h-4" />
                                      <span className="font-semibold text-xs tracking-wide">{timeLeft}</span>
                                   </div>
                              ) : (
                                   <div className="flex items-center gap-1.5 h-6">
                                      <Icons.Gift className="w-5 h-5 animate-bounce" />
                                      <span className="font-semibold tracking-wide">Claim +10</span>
                                      <Icons.Diamond className="w-4 h-4 text-blue-500 fill-current" />
                                   </div>
                              )}
                          </button>
                      </div>
                  </div>

                  {/* Utility Row (Points + Settings) */}
                  <div 
                    className="w-full max-w-md flex items-center justify-center gap-3 mt-6 mb-2 opacity-0 animate-slide-in-down shrink-0" 
                    style={{ animationDelay: '350ms' }}
                  >
                      <div className="flex items-center gap-1.5 bg-t-surface px-3 py-1.5 rounded-full shadow-sm">
                          <span className="text-sm font-semibold text-t-primary tabular-nums leading-none pt-0.5">{points}</span>
                          <div className="text-blue-500"><Icons.Diamond className="w-3.5 h-3.5 fill-current" /></div>
                      </div>

                      <button onClick={(e) => { e.stopPropagation(); sounds.playClick(); onOpenSettings(); }} className="p-1.5 bg-t-surface rounded-full shadow-sm hover:bg-stone-100 dark:hover:bg-stone-800 transition active:scale-95 text-t-icon">
                          <Icons.Settings className="w-5 h-5" />
                      </button>
                  </div>

                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

import { AppSettings, LevelProgress, StoredData, PepinoState } from '../types';
import { Preferences } from '@capacitor/preferences';

const STORAGE_KEY = 'oku_data_v1';
const LEGACY_STORAGE_KEY = 'minimal_sudoku_data_v1';

const DEFAULT_SETTINGS: AppSettings = {
  sound: true,
  highlight: true,
  autoEraseNotes: true, // Default ON
  vibration: true,
  showTimer: true,
  appearance: 'light',
  digitFirst: false, // Default OFF
  screenWakeLock: false, // Default OFF
  generateReplay: true, // Default ON
  hiddenDifficulties: [], // Default show all
};

function getStoredData(): StoredData {
  try {
    let raw = localStorage.getItem(STORAGE_KEY);

    // Migration Logic: Check for legacy key if new key doesn't exist
    if (!raw) {
        const legacyRaw = localStorage.getItem(LEGACY_STORAGE_KEY);
        if (legacyRaw) {
            raw = legacyRaw;
            // Persist migration immediately
            localStorage.setItem(STORAGE_KEY, legacyRaw);
        }
    }

    if (!raw) {
      const initialData: StoredData = { 
          settings: DEFAULT_SETTINGS, 
          points: 0, 
          progress: {},
          purchasedBackgrounds: ['bg-default', 'bg-dyn-default'],
          selectedBackground: 'bg-default',
          purchasedNumberColors: ['num-default'],
          selectedNumberColor: 'num-default',
          purchasedSkills: [],
          enabledSkills: [],
          purchasedSoundPacks: ['snd-zen'],
          selectedSoundPack: 'snd-zen',
          bonusClaimed: false,
          nextBonusClaimTime: 0,
          starterPackPurchased: false,
          unlockedPack2: [],
          unlockedPack3: [],
          pepino: { unlocked: false, lastGiftTime: 0, nextGiftDelay: 0 }
      };

      return initialData;
    }
    const data = JSON.parse(raw);

    // Migrations
    if (typeof data.points !== 'number') data.points = 0;

    if (!data.purchasedBackgrounds) data.purchasedBackgrounds = ['bg-default', 'bg-dyn-default'];
    if (!data.purchasedBackgrounds.includes('bg-default')) data.purchasedBackgrounds.push('bg-default');
    if (!data.purchasedBackgrounds.includes('bg-dyn-default')) data.purchasedBackgrounds.push('bg-dyn-default');

    if (data.selectedBackground === undefined) data.selectedBackground = 'bg-default';

    if (!data.purchasedNumberColors) data.purchasedNumberColors = ['num-default'];
    if (!data.selectedNumberColor) data.selectedNumberColor = 'num-default';

    if (!data.purchasedSoundPacks) data.purchasedSoundPacks = ['snd-zen'];
    if (!data.selectedSoundPack) data.selectedSoundPack = 'snd-zen';

    if (data.settings.vibration === undefined) data.settings.vibration = true;

    if (data.settings.showTimer === undefined) {
        if ((data.settings as any).hideTimer !== undefined) {
            data.settings.showTimer = !(data.settings as any).hideTimer;
            delete (data.settings as any).hideTimer;
        } else {
            data.settings.showTimer = true;
        }
    }

    if (data.settings.autoEraseNotes === undefined) data.settings.autoEraseNotes = true;
    if (data.settings.digitFirst === undefined) data.settings.digitFirst = false;
    if (data.settings.screenWakeLock === undefined) data.settings.screenWakeLock = false;
    if (data.settings.generateReplay === undefined) data.settings.generateReplay = true; // Default ON
    if (data.settings.hiddenDifficulties === undefined) data.settings.hiddenDifficulties = [];

    if (data.settings.appearance === undefined) {
        data.settings.appearance = 'light'; 
    }

    if (!data.purchasedSkills) data.purchasedSkills = [];
    if (!data.enabledSkills) data.enabledSkills = [...data.purchasedSkills]; // Default new field to existing purchased skills

    if (data.bonusClaimed === undefined) data.bonusClaimed = false;
    if (data.nextBonusClaimTime === undefined) data.nextBonusClaimTime = 0;

    if (data.starterPackPurchased === undefined) data.starterPackPurchased = false;

    if (!data.unlockedPack2) data.unlockedPack2 = [];
    if (!data.unlockedPack3) data.unlockedPack3 = [];

    if (!data.pepino) data.pepino = { unlocked: false, lastGiftTime: 0, nextGiftDelay: 0 };

    // Clean up deprecated fields if they exist from previous versions
    if ((data as any).purchasedBundles) delete (data as any).purchasedBundles;

    return data;
  } catch (e) {
    console.error("Failed to load data", e);
    return { 
        settings: DEFAULT_SETTINGS, 
        points: 0, 
        progress: {},
        purchasedBackgrounds: ['bg-default', 'bg-dyn-default'],
        selectedBackground: 'bg-default',
        purchasedNumberColors: ['num-default'],
        selectedNumberColor: 'num-default',
        purchasedSkills: [],
        enabledSkills: [],
        purchasedSoundPacks: ['snd-zen'],
        selectedSoundPack: 'snd-zen',
        bonusClaimed: false,
        nextBonusClaimTime: 0,
        starterPackPurchased: false,
        unlockedPack2: [],
        unlockedPack3: [],
        pepino: { unlocked: false, lastGiftTime: 0, nextGiftDelay: 0 }
    };
  }
}

function saveData(data: StoredData) {
  try {
    const stringified = JSON.stringify(data);
    localStorage.setItem(STORAGE_KEY, stringified);
    Preferences.set({
        key: STORAGE_KEY,
        value: stringified
    }).catch((err: any) => console.error("Native save failed", err));
  } catch (e) {
    console.error("Failed to save data", e);
  }
}

export const Storage = {
  getStoredData, 

  initializeNative: async (): Promise<StoredData | null> => {
      try {
          let { value } = await Preferences.get({ key: STORAGE_KEY });

          // Native Migration Logic
          if (!value) {
              const legacy = await Preferences.get({ key: LEGACY_STORAGE_KEY });
              if (legacy.value) {
                  value = legacy.value;
                  // Persist to new key
                  await Preferences.set({ key: STORAGE_KEY, value: legacy.value });
              }
          }

          if (value) {
              localStorage.setItem(STORAGE_KEY, value);
              return JSON.parse(value);
          }
          return null;
      } catch (e) {
          console.warn("Could not read native prefs", e);
          return null;
      }
  },

  getSettings: (): AppSettings => {
    return getStoredData().settings;
  },

  saveSettings: (settings: AppSettings) => {
    const data = getStoredData();
    data.settings = settings;
    saveData(data);
  },

  getPoints: (): number => {
    return getStoredData().points;
  },

  addPoints: (amount: number) => {
    const data = getStoredData();
    data.points += amount;
    saveData(data);
    return data.points;
  },

  // ... existing methods ...
  getPurchasedBackgrounds: (): string[] => {
      return getStoredData().purchasedBackgrounds;
  },

  getSelectedBackground: (): string | null => {
      return getStoredData().selectedBackground;
  },

  purchaseBackground: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (data.points >= cost && !data.purchasedBackgrounds.includes(id)) {
          data.points -= cost;
          data.purchasedBackgrounds.push(id);
          saveData(data);
          return true;
      }
      return false;
  },

  selectBackground: (id: string | null) => {
      const data = getStoredData();
      data.selectedBackground = id;
      saveData(data);
  },

  getPurchasedNumberColors: (): string[] => {
      return getStoredData().purchasedNumberColors;
  },

  getSelectedNumberColor: (): string => {
      return getStoredData().selectedNumberColor;
  },

  purchaseNumberColor: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (data.points >= cost && !data.purchasedNumberColors.includes(id)) {
          data.points -= cost;
          data.purchasedNumberColors.push(id);
          saveData(data);
          return true;
      }
      return false;
  },

  selectNumberColor: (id: string) => {
      const data = getStoredData();
      data.selectedNumberColor = id;
      saveData(data);
  },

  getPurchasedSoundPacks: (): string[] => {
    return getStoredData().purchasedSoundPacks || ['snd-zen'];
  },

  getSelectedSoundPack: (): string => {
      return getStoredData().selectedSoundPack || 'snd-zen';
  },

  purchaseSoundPack: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (!data.purchasedSoundPacks) data.purchasedSoundPacks = ['snd-zen'];
      if (data.points >= cost && !data.purchasedSoundPacks.includes(id)) {
          data.points -= cost;
          data.purchasedSoundPacks.push(id);
          saveData(data);
          return true;
      }
      return false;
  },

  selectSoundPack: (id: string) => {
      const data = getStoredData();
      data.selectedSoundPack = id;
      saveData(data);
  },

  getPurchasedSkills: (): string[] => {
      return getStoredData().purchasedSkills;
  },

  getEnabledSkills: (): string[] => {
    const data = getStoredData();
    return data.enabledSkills || [];
  },

  purchaseSkill: (id: string, cost: number): boolean => {
      const data = getStoredData();
      if (data.points >= cost && !data.purchasedSkills.includes(id)) {
          data.points -= cost;
          data.purchasedSkills.push(id);
          if (!data.enabledSkills) data.enabledSkills = [];
          if (!data.enabledSkills.includes(id)) data.enabledSkills.push(id); // Auto enable on purchase
          saveData(data);
          return true;
      }
      return false;
  },

  toggleSkillEnabled: (id: string) => {
    const data = getStoredData();
    if (!data.enabledSkills) data.enabledSkills = [];
    if (data.enabledSkills.includes(id)) {
      data.enabledSkills = data.enabledSkills.filter(s => s !== id);
    } else if (data.purchasedSkills.includes(id)) {
      data.enabledSkills.push(id);
    }
    saveData(data);
    return data.enabledSkills;
  },

  isBonusClaimed: (): boolean => {
      return !!getStoredData().bonusClaimed;
  },

  setBonusClaimed: () => {
      const data = getStoredData();
      data.bonusClaimed = true;
      saveData(data);
  },

  getNextBonusClaimTime: (): number => {
      return getStoredData().nextBonusClaimTime || 0;
  },

  setNextBonusClaimTime: (time: number) => {
      const data = getStoredData();
      data.nextBonusClaimTime = time;
      saveData(data);
  },

  isStarterPackPurchased: (): boolean => {
      return !!getStoredData().starterPackPurchased;
  },

  setStarterPackPurchased: () => {
      const data = getStoredData();
      data.starterPackPurchased = true;
      saveData(data);
  },

  getUnlockedPacks2: (): string[] => {
      return getStoredData().unlockedPack2 || [];
  },

  isPack2Unlocked: (difficulty: string): boolean => {
      return getStoredData().unlockedPack2?.includes(difficulty) ?? false;
  },

  unlockPack2: (difficulty: string, cost: number): boolean => {
      const data = getStoredData();
      if (!data.unlockedPack2) data.unlockedPack2 = [];

      if (data.points >= cost && !data.unlockedPack2.includes(difficulty)) {
          data.points -= cost;
          data.unlockedPack2.push(difficulty);
          saveData(data);
          return true;
      }
      return false;
  },

  getUnlockedPacks3: (): string[] => {
      return getStoredData().unlockedPack3 || [];
  },

  isPack3Unlocked: (difficulty: string): boolean => {
      return getStoredData().unlockedPack3?.includes(difficulty) ?? false;
  },

  unlockPack3: (difficulty: string, cost: number): boolean => {
      const data = getStoredData();
      if (!data.unlockedPack3) data.unlockedPack3 = [];

      if (data.points >= cost && !data.unlockedPack3.includes(difficulty)) {
          data.points -= cost;
          data.unlockedPack3.push(difficulty);
          saveData(data);
          return true;
      }
      return false;
  },

  getLevelProgress: (difficulty: string, levelId: number): LevelProgress | undefined => {
    const key = `${difficulty}-${levelId}`;
    return getStoredData().progress[key];
  },

  saveLevelProgress: (progress: LevelProgress) => {
    const data = getStoredData();
    const key = `${progress.difficulty}-${progress.levelId}`;
    const existing = data.progress[key];
    let bestTime = existing?.bestTime;
    if (progress.status === 'completed') {
        if (bestTime === undefined || progress.timeElapsed < bestTime) {
            bestTime = progress.timeElapsed;
        }
    }
    data.progress[key] = {
        ...progress,
        bestTime: bestTime
    };
    saveData(data);
  },

  clearLevelProgress: (difficulty: string, levelId: number) => {
      const data = getStoredData();
      const key = `${difficulty}-${levelId}`;
      if (data.progress[key]) {
           const { bestTime } = data.progress[key];
           data.progress[key] = {
               levelId,
               difficulty: difficulty as any,
               status: 'not-started',
               boardState: undefined,
               timeElapsed: 0,
               bestTime: bestTime,
               scanUses: 3,
               revealUses: 1,
           };
           saveData(data);
      }
  },

  resetAllData: async () => {
    localStorage.removeItem(STORAGE_KEY);
    // Also remove legacy just in case
    localStorage.removeItem(LEGACY_STORAGE_KEY);

    try {
        await Preferences.remove({ key: STORAGE_KEY });
        await Preferences.remove({ key: LEGACY_STORAGE_KEY });
    } catch (e) {
        console.warn("Error removing native preference", e);
    }
  },

  getCompletedCount: (difficulty: string, maxLevel: number = 200): number => {
      const progress = getStoredData().progress;
      return Object.values(progress).filter(p => 
        p.difficulty === difficulty && 
        p.levelId <= maxLevel && 
        (p.status === 'completed' || p.bestTime !== undefined)
      ).length;
  },

  getCompletedCountInRange: (difficulty: string, minLevel: number, maxLevel: number): number => {
      const progress = getStoredData().progress;
      return Object.values(progress).filter(p => 
        p.difficulty === difficulty && 
        p.levelId >= minLevel && 
        p.levelId <= maxLevel && 
        (p.status === 'completed' || p.bestTime !== undefined)
      ).length;
  },

  // PEPINO (Fish) Methods
  getPepinoState: (): PepinoState => {
      const data = getStoredData();
      return data.pepino || { unlocked: false, lastGiftTime: 0, nextGiftDelay: 0 };
  },

  unlockPepino: () => {
      const data = getStoredData();
      if (!data.pepino) data.pepino = { unlocked: true, lastGiftTime: Date.now(), nextGiftDelay: 0 };
      data.pepino.unlocked = true;
      // First gift available instantly for instant delight
      data.pepino.lastGiftTime = Date.now();
      data.pepino.nextGiftDelay = 0;
      saveData(data);
  },

  updatePepinoGiftTime: (delay: number) => {
      const data = getStoredData();
      if (!data.pepino) data.pepino = { unlocked: true, lastGiftTime: 0, nextGiftDelay: 0 };
      data.pepino.lastGiftTime = Date.now();
      data.pepino.nextGiftDelay = delay;
      saveData(data);
  }
};

