        };

        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [nextBonusClaimTime]);

    const handleClose = () => {
        if (!activeInfo) return;
        setIsClosing(true);
        const closingDiff = activeInfo;
        setTimeout(() => {
            setActiveInfo(null);
            setIsClosing(false);
            setInfoIndices(prev => ({
                ...prev,
                [closingDiff]: (prev[closingDiff] || 0) + 1
