        const animate = (currentTime: number) => {
            if (!startTime) startTime = currentTime;
            const progress = Math.min((currentTime - startTime) / duration, 1);

            // Linear interpolation
            const ease = progress;

            setCount(Math.floor(end * ease));

            if (progress < 1) {
                animationFrameId = requestAnimationFrame(animate);
            } else {
                setCount(end);
            }
        };

        if (delay > 0) {
            timeoutId = setTimeout(() => {
                animationFrameId = requestAnimationFrame(animate);
            }, delay);
        } else {
            animationFrameId = requestAnimationFrame(animate);
        }

        return () => {
            if (animationFrameId) cancelAnimationFrame(animationFrameId);
            if (timeoutId) clearTimeout(timeoutId);
        };
    }, [end, duration, delay]);

    return count;
};

export const StatsScreen: React.FC<StatsScreenProps> = ({ onBack }) => {
    const [selectedDiff, setSelectedDiff] = useState<Difficulty>(Difficulty.Normal);
    const [isDiffMenuOpen, setIsDiffMenuOpen] = useState(false);

    const stats = useMemo(() => {
        const allProgress = Storage.getStoredData().progress;
        const result = {
            completed: 0,
            totalTime: 0,
            bestTime: Infinity,
        };

        Object.values(allProgress).forEach(p => {
            // Count as completed if status is 'completed' OR if a bestTime exists (meaning it was solved before)
            if (p.difficulty === selectedDiff && (p.status === 'completed' || p.bestTime !== undefined)) {
                result.completed++;

                // Add time (Logic: If currently in-progress replay, use bestTime for stats to avoid skewing with partial data, 
                // or if completed, use timeElapsed. Since bestTime tracks the best run, using it for total aggregates 
                // is a safe approximation for "time spent winning", though technically total playtime is different.
                // For simplicity and consistency with the "Best" metric, we sum the best times of solved levels.)
                const timeToAdd = p.bestTime !== undefined ? p.bestTime : p.timeElapsed;
                result.totalTime += timeToAdd;

                if (p.bestTime && p.bestTime < result.bestTime) {
                    result.bestTime = p.bestTime;
                }
            }
        });

        return result;
    }, [selectedDiff]);

    const averageTime = stats.completed > 0 ? Math.floor(stats.totalTime / stats.completed) : 0;
    const pointsPerGame = getDifficultyPoints(selectedDiff);
    const totalDiamondsEarned = stats.completed * pointsPerGame;

    // Animated Values - Delayed by 350ms to start after the menu collapse animation (300ms) finishes
    const animatedCompleted = useAnimatedCounter(stats.completed, 1000, 350);
    const animatedBestTime = useAnimatedCounter(stats.bestTime === Infinity ? 0 : stats.bestTime, 1000, 350);
    const animatedTotalTime = useAnimatedCounter(stats.totalTime, 1000, 350);
    const animatedAverageTime = useAnimatedCounter(averageTime, 1000, 350);
    const animatedDiamonds = useAnimatedCounter(totalDiamondsEarned, 1000, 350);

    const formatFullTime = (seconds: number) => {
        const total = Math.floor(seconds);
        const h = Math.floor(total / 3600);
        const m = Math.floor((total % 3600) / 60);
        const s = total % 60;

        const mStr = m.toString().padStart(2, '0');
        const sStr = s.toString().padStart(2, '0');

        if (h > 0) return `${h}h ${mStr}m ${sStr}s`;
        return `${mStr}m ${sStr}s`;
    };

    const handleToggleMenu = () => {
        sounds.playClick();
        setIsDiffMenuOpen(!isDiffMenuOpen);
    };

    const handleSelectDiff = (diff: Difficulty) => {
        sounds.playClick();
        setSelectedDiff(diff);
        setIsDiffMenuOpen(false);
    };

    return (
        <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
            {/* Header */}
            <div className="w-full max-w-md flex items-center justify-between px-6 pt-4 pb-4 relative shrink-0 z-20">
                <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200 transition -ml-2 text-t-icon relative z-30">
                    <Icons.Back className="w-6 h-6 text-t-icon" />
                </button>

                <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                    <h1 className="text-xl font-bold text-t-primary leading-none">Statistics</h1>
                    <p className="text-t-secondary text-[10px] font-bold tracking-widest uppercase mt-1">Your Progress</p>
                </div>

                {/* Spacer to balance the layout for centering */}
                <div className="w-10"></div>
            </div>

            {/* Content */}
            <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                <div className="w-full max-w-md pt-2">

                    {/* Collapsible Difficulty Menu (Accordion Style) */}
                    <div className="w-full mb-6 z-20">
                        <button 
                            onClick={handleToggleMenu}
                            className="w-full bg-t-surface p-4 rounded-2xl shadow-sm flex items-center justify-between active:scale-[0.98] transition-all relative z-10"
                        >
                            <span className="text-lg font-bold text-t-primary">{selectedDiff}</span>
                            <Icons.Back className={`w-5 h-5 text-t-secondary transition-transform duration-300 ${isDiffMenuOpen ? '-rotate-90' : '-rotate-180'}`} /> 
                        </button>

                        {/* Accordion Content */}
                        <div className={`overflow-hidden transition-all duration-300 ease-in-out ${isDiffMenuOpen ? 'max-h-[400px] opacity-100 mt-2' : 'max-h-0 opacity-0 mt-0'}`}>
                            <div className="bg-t-surface rounded-2xl shadow-sm overflow-hidden flex flex-col">
                                {Object.values(Difficulty).map((diff) => (
                                    <button
                                        key={diff}
                                        onClick={() => handleSelectDiff(diff)}
                                        className={`w-full text-left px-5 py-4 text-lg font-bold border-b border-stone-200 dark:border-stone-700 last:border-0 hover:bg-stone-50 dark:hover:bg-stone-800 transition-colors ${selectedDiff === diff ? 'text-blue-500 bg-blue-50/50 dark:bg-blue-900/10' : 'text-t-primary'}`}
                                    >
                                        {diff}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* Big Numbers Grid */}
                    <div className="grid grid-cols-2 gap-4 mb-4">
                        {/* Completed Games */}
                        <div className="bg-t-surface p-6 rounded-3xl shadow-sm flex flex-col items-center text-center">
                            <div className="w-12 h-12 bg-green-100 text-green-600 dark:bg-green-900/30 dark:text-green-400 rounded-full flex items-center justify-center mb-3">
                                <Icons.Check className="w-6 h-6 stroke-[3]" />
                            </div>
                            <span className="text-3xl font-bold text-t-primary mb-1">{animatedCompleted}</span>
                            <span className="text-xs font-bold text-t-secondary uppercase tracking-wider">Solved</span>
                        </div>

                        {/* Best Time */}
                        <div className="bg-t-surface p-6 rounded-3xl shadow-sm flex flex-col items-center text-center">
                            <div className="w-12 h-12 bg-amber-100 text-amber-600 dark:bg-amber-900/30 dark:text-amber-400 rounded-full flex items-center justify-center mb-3">
                                <Icons.Sparkles className="w-6 h-6" />
                            </div>
                            <span className="text-3xl font-bold text-t-primary mb-1">
                                {stats.bestTime === Infinity ? '--' : formatTimeShort(animatedBestTime)}
                            </span>
                            <span className="text-xs font-bold text-t-secondary uppercase tracking-wider">Best Time</span>
                        </div>
                    </div>

                    {/* Detailed Stats Card */}
                    <div className="bg-t-surface rounded-3xl shadow-sm overflow-hidden mb-6">
                        {/* Total Time */}
                        <div className="p-5 border-b border-stone-200 dark:border-stone-700 flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400 rounded-full flex items-center justify-center">
                                    <Icons.Clock className="w-5 h-5" />
                                </div>
                                <span className="text-xs font-bold text-t-secondary uppercase tracking-wider">Total Time</span>
                            </div>
                            <span className="text-lg font-bold text-t-primary">
                                {formatFullTime(animatedTotalTime)}
                            </span>
                        </div>

                        {/* Average Time */}
                        <div className="p-5 border-b border-stone-200 dark:border-stone-700 flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-purple-100 text-purple-600 dark:bg-purple-900/30 dark:text-purple-400 rounded-full flex items-center justify-center">
                                    <Icons.BarChart className="w-5 h-5" />
                                </div>
                                <span className="text-xs font-bold text-t-secondary uppercase tracking-wider">Average Time</span>
                            </div>
                            <span className="text-lg font-bold text-t-primary">
                                {averageTime === 0 ? '--' : formatFullTime(animatedAverageTime)}
                            </span>
                        </div>

                        {/* Diamonds Earned */}
                        <div className="p-5 flex items-center justify-between bg-gradient-to-r from-transparent via-blue-50/20 to-transparent dark:via-blue-900/5">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-blue-50 text-blue-500 dark:bg-blue-900/20 dark:text-blue-300 rounded-full flex items-center justify-center shadow-inner">
                                    <Icons.Diamond className="w-5 h-5 fill-current" />
                                </div>
                                <div className="flex flex-col">
                                    <span className="text-xs font-bold text-t-secondary uppercase tracking-wider">Diamonds Earned</span>
                                    <span className="text-[10px] font-medium text-blue-400 dark:text-blue-500 tracking-tight leading-none mt-0.5">+{pointsPerGame} per game</span>
                                </div>
                            </div>
                            <div className="flex items-center gap-2">
                                <span className="text-xl font-bold text-t-primary">
                                    {animatedDiamonds.toLocaleString()}
                                </span>
                                <Icons.Diamond className="w-4 h-4 text-blue-500 fill-current" />
                            </div>
                        </div>
                    </div>

                </div>
            </div>
        </div>
    );
};

import React from 'react';
import { Difficulty } from '../../types';
import { Storage } from '../../utils/storage';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { UnlockCard } from '../ui/UnlockCard';
import { getPackCost, formatTimeShort } from '../../utils/constants';

interface LevelsScreenProps {
    difficulty: Difficulty;
    points: number;
    unlockedPacks2: string[];
    unlockedPacks3: string[];
    onBack: () => void;
    onLevelSelect: (levelId: number) => void;
    onOpenSettings: () => void;
    onUnlockPack2: () => void;
    onUnlockPack3: () => void;
}

export const LevelsScreen: React.FC<LevelsScreenProps> = ({ 
    difficulty, 
    points,
    unlockedPacks2, 
    unlockedPacks3, 
    onBack, 
    onLevelSelect, 
    onOpenSettings,
    onUnlockPack2,
    onUnlockPack3
}) => {
    // Logic for Levels & Unlocking
    const isPack2Unlocked = unlockedPacks2.includes(difficulty);
    const isPack3Unlocked = unlockedPacks3.includes(difficulty);

    let totalVisibleLevels = 100;
    if (isPack2Unlocked) totalVisibleLevels = 200;
    if (isPack3Unlocked) totalVisibleLevels = 300;

    const allLevels = Array.from({ length: totalVisibleLevels }, (_, i) => i + 1);

    // Count completed levels for specific ranges to drive unlock cards
    const completedRange1 = Storage.getCompletedCountInRange(difficulty, 1, 100);
    const completedRange2 = Storage.getCompletedCountInRange(difficulty, 101, 200);

    // Global Best for Header
    let globalBest = Infinity;
    allLevels.forEach(l => {
        const p = Storage.getLevelProgress(difficulty, l);
        if (p?.bestTime !== undefined && p.bestTime < globalBest) {
            globalBest = p.bestTime;
        }
    });
    const hasGlobalBest = globalBest !== Infinity;

    return (
        <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
            <div className="w-full max-w-md flex items-center justify-between px-6 pt-4 pb-4 relative shrink-0 z-20">
                <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200/50 transition -ml-2 text-t-icon relative z-30">
                    <Icons.Back className="w-6 h-6 text-t-icon" />
                </button>

                <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                    <h1 className="text-xl font-bold leading-none">{difficulty}</h1>
                    <p className="text-xs text-t-secondary uppercase tracking-widest mt-1">Select Level</p>
                    {hasGlobalBest && (
                        <div className="flex flex-col items-center animate-fade-in mt-1">
                            <span className="text-[10px] font-bold text-amber-500 tracking-widest uppercase mb-px opacity-90">Best: {formatTimeShort(globalBest)}</span>
                        </div>
                    )}
                </div>

                <button onClick={() => { sounds.playClick(); onOpenSettings(); }} className="p-2 rounded-full hover:bg-stone-200/50 transition -mr-2 text-t-icon relative z-30">
                    <Icons.Settings className="w-6 h-6 text-t-icon" />
                </button>
            </div>

            <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center">
                <div className="w-full max-w-md grid grid-cols-5 gap-3 pt-2">
                    {allLevels.map((lvl) => {
                            const progress = Storage.getLevelProgress(difficulty, lvl);
                            const bestTime = progress?.bestTime;

                            // A level is considered "Solved" if it has a bestTime recorded (history of winning)
                            // or if the current status is completed (fresh win)
                            const isSolved = bestTime !== undefined || progress?.status === 'completed';
                            const isInProgress = progress?.status === 'in-progress';
                            const isGlobalBest = hasGlobalBest && bestTime !== undefined && bestTime === globalBest;

                            // Style Logic:
                            // - Solved levels always use the 'Completed' background (bg-t-surface-sec) to show they are done.
                            // - If Solved AND In-Progress (Replaying), we add a Blue Ring to show activity, but keep background grey/completed.
                            // - If Not Solved AND In-Progress, we use White/Surface background with Blue Ring.

                            let buttonClass = 'aspect-square rounded-xl relative transition-all active:scale-90 shadow-sm ';

                            if (isSolved) {
                                buttonClass += 'bg-t-surface-sec text-t-secondary ring-1 ring-inset ring-stone-900/5 ';
                                if (isInProgress) {
                                    // Replaying: Add active ring and clearer text color
                                    buttonClass += '!ring-2 !ring-blue-400 !text-t-primary ';
                                }
                            } else if (isInProgress) {
                                // First time playing, active
                                buttonClass += 'bg-t-surface ring-2 ring-blue-400 shadow-md text-t-primary ';
                            } else {
                                // Not started
                                buttonClass += 'bg-t-surface hover:shadow-md text-t-primary ';
                            }

                            return (
                                <button key={lvl} onClick={() => onLevelSelect(lvl)} className={buttonClass}>
                                    <div className="absolute inset-0 flex items-center justify-center"><span className="font-bold text-2xl leading-none">{lvl}</span></div>
                                    {bestTime ? (
                                        isGlobalBest ? (
                                            <>
                                                <div className="absolute top-1.5 inset-x-0 flex justify-center">
                                                    <span className="text-[8px] font-bold text-amber-500 tracking-widest opacity-90 animate-pulse">BEST</span>
                                                </div>
                                                <div className="absolute bottom-1.5 inset-x-0 flex justify-center">
                                                    <span className="text-[10px] text-amber-500 font-bold tracking-tight block leading-none animate-pulse">{formatTimeShort(bestTime)}</span>
                                                </div>
                                            </>
                                        ) : (
                                            <div className="absolute bottom-1.5 inset-x-0 text-center">
                                                <span className={`text-[10px] font-bold tracking-tight block ${isInProgress ? 'text-t-primary' : 'text-t-secondary'}`}>{formatTimeShort(bestTime)}</span>
                                            </div>
                                        )
                                    ) : null}
                                </button>
                            );
                    })}
                </div>

                {/* Unlock Card Logic - Chained */}
                {!isPack2Unlocked && (
                    <UnlockCard 
                        startLevel={101}
                        endLevel={200}
                        completedCount={completedRange1}
                        totalBaseLevels={100}
                        cost={getPackCost(difficulty, 2)}
                        onUnlock={onUnlockPack2}
                    />
                )}

                {isPack2Unlocked && !isPack3Unlocked && (
                        <UnlockCard 
                        startLevel={201}
                        endLevel={300}
                        completedCount={completedRange2}
                        totalBaseLevels={100}
                        cost={getPackCost(difficulty, 3)}
                        onUnlock={onUnlockPack3}
                    />
                )}

                <div className="h-safe-bottom w-full shrink-0" />
            </div>
        </div>
    );
};
